297: Check("a completed held meal sweet or drink releases needs after its actual swallowing response",()=>
298: {
299:     foreach(var action in new[]{InteractionAction.FeedMeal,InteractionAction.FeedSweet,InteractionAction.Drink})
300:     foreach(string need in new[]{"food","water","rest"})
301:     {
302:         var sim=CompletionFixture();var c=sim.Selected!;
303:         if(need=="food")c.Fullness=25;else if(need=="water")c.Interaction.Hydration=20;else c.Energy=10;
304:         var destination=new RoomObject{Id="destination",Kind=need=="food"?RoomObjectKind.Meal:need=="water"?RoomObjectKind.Water:RoomObjectKind.Cushion,X=2,Z=0,Portions=5};
305:         var held=new RoomObject{Id="held",Kind=action==InteractionAction.Drink?RoomObjectKind.Water:action==InteractionAction.FeedSweet?RoomObjectKind.Sweet:RoomObjectKind.Meal,X=-3,Z=0,Portions=2};
306:         sim.State.RoomObjects.Add(destination);sim.State.RoomObjects.Add(held);Require(sim.HoldSupply(held.Id),"could not pick up fixture supply");
307:         int stock=sim.State.Food;var input=new InteractionInput(action,BodyPart.Mouth,Force:.2,Duration:.05,ObjectId:held.Id);
308:         Require(sim.BeginInteractionGesture(c.Id,input).Success&&sim.InteractionGestureOwnsPose,"mouth invitation lost its contact phase");
309:         bool accepted=false,moved=false,sawSwallow=false,sawNaturalIntake=false;
310:         double startX=c.X,startZ=c.Z,peakX=c.X,maxDistanceFromStart=0,totalTravel=0;
311:         double closestDestination=WorldSimulation.Distance(c.X,c.Z,destination.X,destination.Z);
312:         bool sawDestinationIntake=false,returnedAfterDestination=false;
313:         string lastDisplayedPose="";
314:         for(int n=0;n<240;n++)
315:         {
316:             var frame=HeldFrame(sim,input);
317:             // Diagnostics only: observe the unchanged frame sequence and predicates.
318:             peakX=Math.Max(peakX,c.X);totalTravel+=frame.Travel;
319:             maxDistanceFromStart=Math.Max(maxDistanceFromStart,WorldSimulation.Distance(startX,startZ,c.X,c.Z));
320:             closestDestination=Math.Min(closestDestination,WorldSimulation.Distance(c.X,c.Z,destination.X,destination.Z));
321:             sawDestinationIntake|=c.Interaction.GroundIntake&&c.Interaction.EatingRemaining>0&&c.Interaction.GroundIntakeSourceId==destination.Id;
322:             returnedAfterDestination|=sawDestinationIntake&&c.X<=.5;
323:             lastDisplayedPose=frame.Pose;
324:             accepted|=sim.InteractionIntakeAccepted;
325:             Require(held.HeldByHand&&held.Portions==(accepted?1:2)&&sim.State.Food==stock,"held portion was repeated, refunded or automatically put down");
326:             if(accepted)Require(sim.InteractionIntakeAccepted&&!sim.InteractionGestureOwnsPose,"completed food reclaimed body pose or lost acceptance");
327:             if(!moved&&frame.Pose=="swallow")sawSwallow=true;
328:             if(!moved&&frame.Travel>.000001)
329:             {
330:                 Require(accepted&&frame.Pose is "idle" or "guard" or "stomach" or "careful-step",$"{action}/{need}: first movement kept {frame.Pose}");
331:                 moved=true;
332:             }
333:             if(c.Interaction.GroundIntake&&c.Interaction.EatingRemaining>0)
334:             {
335:                 sawNaturalIntake=true;
336:                 Require(!sim.InteractionGestureOwnsPose,"later autonomous mouthful reacquired the completed feeding gesture");
337:             }
338:         }
339:         Require(accepted&&sawSwallow&&moved&&c.X>.5,$"{action}/{need}: holding the finished tool trapped the oil or skipped swallowing; diagnostics="+
340:             JsonSerializer.Serialize(new{accepted,sawSwallow,moved,sawNaturalIntake,endX=c.X,endZ=c.Z,peakX,maxDistanceFromStart,totalTravel,
341:                 closestDestination,sawDestinationIntake,returnedAfterDestination,destinationId=destination.Id,destinationX=destination.X,destinationZ=destination.Z,
342:                 destinationPortions=destination.Portions,targetX=c.TargetX,targetZ=c.TargetZ,c.Activity,c.Fullness,c.Energy,c.Interaction.Hydration,
343:                 c.Interaction.EatingRemaining,c.Interaction.GroundIntake,c.Interaction.GroundIntakeSourceId,c.Interaction.NaturalIntakePending,
344:                 lastDisplayedPose,c.Interaction.ReactionPose,c.Interaction.ReactionPoseRemaining,c.Interaction.ReactionSituation,c.Interaction.ReactionRefused,
345:                 sim.HasInteractionGesture,sim.InteractionGestureTarget,sim.CurrentInteractionAction,sim.InteractionGestureOwnsPose,sim.InteractionIntakeAccepted,
346:                 c.Interaction.Carried,c.Interaction.Falling,c.Interaction.Restraint,excretionActive=c.Interaction.Physiology.Active,c.Interaction.Resting}));
347:         Require(need=="rest"?c.Interaction.Resting&&c.Energy>10:sawNaturalIntake&&destination.Portions<5,"autonomous need never completed after release");
348:         double fullness=c.Fullness,water=c.Interaction.Hydration;
349:         sim.EndInteractionGesture(true);
350:         Require(!sim.InteractionIntakeAccepted&&held.HeldByHand&&held.Portions==1&&c.Fullness==fullness&&c.Interaction.Hydration==water,"cancellation refunded food or implicitly released the held container");
351:         Require(sim.ReleaseSupply(held.Id)&&!held.HeldByHand,"explicit put-down failed after completed feeding");
352:     }
353: });

604: Check("an autonomous invitation supplies the same body pose used by the renderer",()=>
605: {
606:     var sim=Fresh();var c=sim.Selected!;c.Fullness=90;c.Interaction.Hydration=90;c.Energy=80;c.Fear=0;c.Trust=80;
607:     c.Interaction.NextAutonomyAt=0;c.Interaction.NuzzleFamiliarity=30;sim.State.RoomObjects.Clear();
608:     sim.SetInteractionHand(c.X,c.Z+.5,true);
609:     Tick(sim,5);
610:     Require(InteractionPresentation.Pose(c)=="invite"&&c.Speech.Contains("蹭"),$"autonomous invitation lacks a pose or matching speech: {InteractionPresentation.Pose(c)}, {c.Speech}");
611:     sim.State.Settings.Pause=true;double remaining=c.Interaction.ReactionPoseRemaining;
612:     sim.AdvanceInteractionPresentation(.1);Require(c.Interaction.ReactionPoseRemaining==remaining,"pause advanced the reaction");
613:     sim.State.Settings.Pause=false;sim.State.Mode=PlayMode.CloseUp;Tick(sim,30);
614:     Require(InteractionPresentation.Pose(c)=="idle","short invitation is stuck after the response window");
615: });

661: Check("voice intent follows the oil's actual response instead of the last selected tool group",()=>
662: {
663:     var sim=Fresh();var c=sim.Selected!;c.Fear=0;c.Trust=80;c.Interaction.NuzzleFamiliarity=30;c.Interaction.NextAutonomyAt=0;c.Fullness=90;c.Interaction.Hydration=90;
664:     sim.SetInteractionHand(c.X,c.Z+.5,true);
665:     Tick(sim,5);Require(InteractionPresentation.VoiceCue(c)=="coo-nuzzle","autonomous nuzzle request has no matching sound intent");
666:     c.Fear=80;c.Trust=5;
667:     sim.ExecuteInteraction(c.Id,new(InteractionAction.Comfort));
668:     Require(InteractionPresentation.VoiceCue(c)=="coo-refuse","refusal sounds like accepted affection");
669:     c.Fear=0;sim.ExecuteInteraction(c.Id,new(InteractionAction.Flick,BodyPart.Head));
670:     Require(InteractionPresentation.VoiceCue(c)=="coo-hurt","hurt response has no matching sound intent");
671: });

1305: Check("stored treasure keeps ownership through save and cannot be displayed as present",()=>
1306: {
1307:     var sim=Fresh();var c=sim.Selected!;sim.ExecuteInteraction(c.Id,new(InteractionAction.GiveTreasure));
1308:     var item=sim.State.RoomObjects.Single(o=>o.Kind==RoomObjectKind.Treasure);sim.PutAwayRoomObject(item.Id);
1309:     var state=JsonSerializer.Deserialize<WorldState>(JsonSerializer.Serialize(sim.State,SaveStore.JsonOptions),SaveStore.JsonOptions)!;
1310:     SaveStore.Validate(state);sim=new WorldSimulation(state);c=sim.Selected!;c.Fullness=90;c.Interaction.Hydration=90;c.Interaction.NextAutonomyAt=0;
1311:     Tick(sim,5);
1312:     Require(state.RoomObjects.Any(o=>o.Id==item.Id&&o.Stored&&o.OwnerId==c.Id)&&c.Interaction.ReactionSituation=="treasure-missing","saving lost ownership or autonomy displayed a stored object");
1313: });
